"use client";
// ─────────────────────────────────────────────────────────────
// components/GTMProvider.jsx
//
// Fires a virtual pageview on every Next.js client-side navigation.
// Wrap your root layout with this — it handles the case where the
// browser never does a full reload between pages.
//
// Why this is needed:
//   Next.js App Router uses the History API for navigation.
//   GTM's built-in "Page View" trigger only fires on window.onload.
//   So without this, GA4 / GTM sees only the first page load.
// ─────────────────────────────────────────────────────────────
import { useEffect, useRef } from "react";
import { usePathname, useSearchParams } from "next/navigation";
import { gtmPageview } from "@/lib/gtm";

export default function GTMProvider({ children }) {
  const pathname = usePathname();
  const searchParams = useSearchParams();

  // Track previous URL to avoid double-firing on mount
  const prevUrl = useRef(null);

  useEffect(() => {
    // Build full URL including query string
    const qs = searchParams.toString();
    const url = qs ? `${pathname}?${qs}` : pathname;

    // Skip if URL hasn't changed (strict mode double-invoke guard)
    if (url === prevUrl.current) return;
    prevUrl.current = url;

    // Small tick delay so document.title has updated by the time we read it
    const timer = setTimeout(() => {
      gtmPageview(url);
    }, 0);

    return () => clearTimeout(timer);
  }, [pathname, searchParams]);

  return children;
}